// Captured from src/main/local/git/parse.ts (SHA-256 1ae6eb5f005f20bd149765c6b85d14e589f7a04f81f9eb357e6211ebad19f8b0).
#[test]
fn draft_helpers_match_typescript_parser() {
    let captured: Value = serde_json::from_str(r###"{"sha256":"1ae6eb5f005f20bd149765c6b85d14e589f7a04f81f9eb357e6211ebad19f8b0","render":[{"template":"{{a}}{{#if b}}[{{b}}]{{/if}}","vars":{"a":"x","b":""},"expected":"x"},{"template":"{{a}}{{#if b}}[{{b}}]{{/if}}","vars":{"a":"x","b":"y"},"expected":"x[y]"},{"template":"{{a}} {{unknown}}","vars":{"a":"{{unknown}}"},"expected":"{{unknown}} "},{"template":"{{#if a}}yes{{/if}}","vars":{"a":"0"},"expected":"yes"},{"template":"{{#if a}}no{{/if}}","vars":{},"expected":""}],"extract":[{"input":"Working...\n```json\n{\"title\":\"t {x}\",\"body\":\"## S\\n- a\"}\n```","expected":{"title":"t {x}","body":"## S\n- a"}},{"input":"{bad} nothing","expected":null},{"input":"noise {\"x\":{\"title\":\"nested\",\"body\":\"yes\"}}","expected":{"title":"nested","body":"yes"}},{"input":"{\"title\":1,\"body\":\"x\"} {\"title\":\"ok\",\"body\":\"  b  \"}","expected":{"title":"ok","body":"  b  "}},{"input":"{\"title\":\"a \\\" } { \",\"body\":\"b\"}","expected":{"title":"a \" } { ","body":"b"}},{"input":"{\"title\":\"\",\"body\":\"\"}","expected":{"title":"","body":""}},{"input":"","expected":null}]}"###).expect("captured JSON");
    for row in captured["render"].as_array().expect("render cases") {
        let vars: Vec<(&str, String)> = row["vars"].as_object().expect("vars").iter().map(|(key, value)| (key.as_str(), value.as_str().expect("text").to_owned())).collect();
        assert_eq!(render_draft_prompt(row["template"].as_str().expect("template"), &vars), row["expected"].as_str().expect("expected"));
    }
    for row in captured["extract"].as_array().expect("extract cases") {
        let actual = extract_draft(row["input"].as_str().expect("input"));
        let expected = row["expected"].as_object().map(|v| (v["title"].as_str().expect("title").to_owned(), v["body"].as_str().expect("body").to_owned()));
        assert_eq!(actual, expected);
    }
}

#[test]
fn draft_accepts_surrogates_at_the_native_string_boundary() {
    assert_eq!(
        extract_draft(r#"{"title":"\ud800","body":"\ud83d\ude00"}"#),
        Some(("\u{fffd}".to_owned(), "😀".to_owned())),
    );
}

